    if (!next) return null;
    const j = skipWhile(
      after,
      k + 1,
      (t) =>
        ["ne", "n'", "pas", "rien", "jamais", "plus", "point"].includes(t.w) ||
        INFINITIVE_CLITICS.has(t.w),
    );
    const infinitive =
      after[j] && verbReadings(after[j].w).some((r) => r.slot === "I" && r.lemma === after[j].w);
    if (!(
      next.w === "que" ||
      next.w === "qu'" ||
      ((next.w === "de" || next.w === "d'") && infinitive)
    ))
      return null;
