      previous &&
      !clauseSubject &&
      /^\p{Ll}/u.test(ctx.text.slice(previous.start, previous.end)) &&
      !isVerbHomograph(previous.w) &&
      verbReadings(previous.w).some((r) => typeof r.slot === "number" && r.lemma !== "pouvoir");
